export function EnterExitAnimation({
  state = "{{state}}",
  style = "{{style}}",
  duration = {{duration}},
  accent = "{{accent}}",
}) {
  const anims = {
    "entering-fade-slide": "mot-eea-enter-slide",
    "exiting-fade-slide": "mot-eea-exit-slide",
    "entering-scale": "mot-eea-enter-scale",
    "exiting-scale": "mot-eea-exit-scale",
  };
  const name = anims[`${state}-${style}`];
  return (
    <div style={{ width: "100%", maxWidth: 320, minHeight: 130, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <div className="card" style={{ background: "#fff", border: `2px solid ${accent}`, borderRadius: 10, padding: "12px 14px", color: "#241430", fontSize: 14 }}>
        <strong>Toast notification</strong>
        <p>Saved successfully.</p>
      </div>
      <p style={{ margin: "10px 0 0" }}>{state} &middot; {style} &middot; replays each time the panel re-renders</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .card { animation: ${name} ${duration}ms ${state === "entering" ? "ease-out" : "ease-in"} both; }
          @keyframes mot-eea-enter-slide { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: translateY(0); } }
          @keyframes mot-eea-exit-slide { from { opacity: 1; transform: translateY(0); } to { opacity: 0; transform: translateY(14px); } }
          @keyframes mot-eea-enter-scale { from { opacity: 0; transform: scale(.85); } to { opacity: 1; transform: scale(1); } }
          @keyframes mot-eea-exit-scale { from { opacity: 1; transform: scale(1); } to { opacity: 0; transform: scale(.85); } }
        }
      `}</style>
    </div>
  );
}
